// Spec 19–21: legal and accessibility pages (#/terms, #/privacy, #/accessibility) and the small display-settings
// panel (text size / contrast / underlined links). Terms and privacy are DRAFTS for the lawyer; the open legal
// questions live in docs/legal/open-questions-he.md, never on the public page.
// Fields the owner must fill are rendered with fill() so they are easy to spot before go-live.
import { contact } from './data.mjs';
import { t, lang, fmtDate } from './i18n.mjs';
import { termsEn, privacyEn, accessibilityEn } from './locales/legal-en.mjs';

const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const fill = what => `<mark class="fill-in">[${t('content.legal.fill', { what })}]</mark>`;
const draft = `<p class="draft-banner" role="note">${t('content.legal.draft')}</p>`;
export const LAST_A11Y_CHECK = '15.11.2026';
const LEGAL_UPDATED = '15.11.2026';
const phoneText = () => contact.phone ? `<a href="tel:${esc(contact.phone)}" dir="ltr">${esc(contact.phone)}</a>` : fill(t('content.legal.phone'));
const mailText = () => contact.email ? `<a href="mailto:${esc(contact.email)}" dir="ltr">${esc(contact.email)}</a>` : fill(t('content.legal.email'));
const toc = items => `<nav class="legal-toc" aria-label="${t('content.legal.toc')}"><ol>${items.map(([id, label]) => `<li><a href="#${id}" data-legal-jump="${id}">${label}</a></li>`).join('')}</ol></nav>`;
const section = (id, title, body) => `<section id="${id}" aria-labelledby="${id}-h"><h2 id="${id}-h" tabindex="-1">${title}</h2>${body}</section>`;

// ---- Display settings (a convenience, not a substitute for the real fixes) ----
const PREFS_KEY = 'gerbi-display-prefs-v1';
const PREFS = [['text', t('content.display.text'), 'a11y-text-lg'], ['contrast', t('content.display.contrast'), 'a11y-contrast'], ['links', t('content.display.links'), 'a11y-links'], ['motion', t('content.display.motion'), 'a11y-still']];
function readPrefs() { try { return JSON.parse(localStorage.getItem(PREFS_KEY) || '{}') || {}; } catch { return {}; } }
export function applyDisplayPrefs(prefs = readPrefs()) {
  for (const [key, , cls] of PREFS) document.documentElement.classList.toggle(cls, Boolean(prefs[key]));
}
function displaySettingsHtml() {
  const prefs = readPrefs();
  return `<section class="surface-panel display-settings" aria-labelledby="display-settings-h"><h2 id="display-settings-h">${t('content.display.title')}</h2>
   <p class="micro-copy">${t('content.display.note')}</p>
   <div class="display-toggles" role="group" aria-label="${t('content.display.title')}">${PREFS.map(([key, label]) => `<button type="button" class="chip-toggle" data-display-pref="${key}" aria-pressed="${Boolean(prefs[key])}">${label}</button>`).join('')}
   <button type="button" class="text-button" data-display-reset>${t('content.display.reset')}</button></div></section>`;
}
if (typeof document !== 'undefined') {
  applyDisplayPrefs();
  document.addEventListener('click', e => {
    const toggle = e.target.closest('[data-display-pref]'), reset = e.target.closest('[data-display-reset]'), jump = e.target.closest('[data-legal-jump]');
    if (jump) { e.preventDefault(); const target = document.getElementById(jump.dataset.legalJump + '-h'); target?.scrollIntoView({ block: 'start' }); target?.focus({ preventScroll: true }); return; }
    if (!toggle && !reset) return;
    const prefs = reset ? {} : { ...readPrefs(), [toggle.dataset.displayPref]: toggle.getAttribute('aria-pressed') !== 'true' };
    try { localStorage.setItem(PREFS_KEY, JSON.stringify(prefs)); } catch {}
    applyDisplayPrefs(prefs);
    document.querySelectorAll('[data-display-pref]').forEach(b => b.setAttribute('aria-pressed', String(Boolean(prefs[b.dataset.displayPref]))));
  });
}

// ---- Pages ----
function terms() {
  const items = [['t-about', 'מי אנחנו ומה תפקידנו'], ['t-use', 'השימוש באתר'], ['t-prices', 'מחירים, זמינות ובדיקת מחיר'], ['t-order', 'הצעה, הזמנה ותשלום'], ['t-cancel', 'ביטולים ושינויים'], ['t-consumer', 'ביטול עסקה לפי חוק הגנת הצרכן'], ['t-docs', 'דרכונים, אשרות ובריאות'], ['t-airline', 'אחריות חברות התעופה והספקים'], ['t-liability', 'הגבלת אחריות'], ['t-content', 'תוכן, השראה ובוט שירות'], ['t-account', 'חשבון לקוח'], ['t-privacy', 'פרטיות'], ['t-ip', 'קניין רוחני'], ['t-law', 'דין ושיפוט'], ['t-contact', 'יצירת קשר']];
  return `${draft}<p class="micro-copy">עודכן לאחרונה: ${LEGAL_UPDATED}. התנאים מנוסחים בלשון רבים ומתייחסים לכל המגדרים.</p>${toc(items)}<div class="article-body legal-body">
  ${section('t-about', '1. מי אנחנו ומה תפקידנו', `<p>האתר מופעל ע״י ג׳רבי טורס (${fill('שם הישות המשפטית')}, ח.פ./ע.מ. ${fill('מספר')}, כתובת: ${fill('כתובת רשומה')}) — „הסוכנות”, „אנחנו”.</p>
   <p>ג׳רבי טורס היא סוכנות נסיעות. אנחנו מחפשים עבורכם טיסות ושירותי תיירות דרך ספקים (מערכות הזמנה וסיטונאים) ומול חברות התעופה, ומעניקים לכם את השירות בעצמנו: מענה, בדיקת מחיר, הצעה, הזמנה וליווי. <strong>אנחנו לא חברת התעופה ולא מפעילים את הטיסה</strong>; ההובלה האווירית עצמה ניתנת ע״י חברת התעופה לפי תנאי ההובלה שלה.</p>`)}
  ${section('t-use', '2. השימוש באתר', `<p>השימוש באתר מותנה בתנאים אלה. אם אינכם מסכימים להם, אנא אל תשתמשו באתר. אין לבצע באתר פעולות אוטומטיות (סריקה, הצפה בבקשות), להתחזות לאחר או להזין מידע כוזב. אנו רשאים לחסום שימוש שפוגע באתר, בספקים או בלקוחות אחרים.</p>`)}
  ${section('t-prices', '3. מחירים, זמינות ובדיקת מחיר', `<ul><li>מחירי טיסות מתקבלים מהספקים בזמן אמת ומשתנים כל הזמן. <strong>מחיר המוצג באתר אינו הצעה מחייבת ואינו שמירת מקום</strong>; הוא נקבע סופית רק עם הנפקת הכרטיס.</li>
   <li>„בדיקת מחיר” מוודאת מול הספק את המחיר והזמינות ברגע הבדיקה בלבד. גם מחיר שנבדק עשוי להשתנות עד להזמנה ולהנפקה.</li>
   <li>מחירים בשקלים מחושבים לפי שער העברות והמחאות – מכירה, ולכן עשויים להשתנות עם השער. המחיר לחיוב ייקבע בהצעה שתקבלו.</li>
   <li>המחיר כולל מסים והיטלים שמסר הספק. ${fill('האם המחיר כולל דמי טיפול של הסוכנות, ובאיזה סכום')}. כבודה, בחירת מושב ושירותים נוספים — לפי מה שמצוין בפרטי הטיסה ובכללי התעריף.</li>
   <li>„רעיונות לחופשה”, מלונות וחבילות המוצגים לצורך השראה הם אומדנים להמחשה בלבד ואינם הצעה.</li>
   <li>טעות סופר או טעות ברורה במחיר אינה מחייבת את הסוכנות; במקרה כזה נפנה אליכם לפני כל חיוב.</li></ul>`)}
  ${section('t-order', '4. הצעה, הזמנה ותשלום', `<ul><li>בשלב זה אין באתר הזמנה או תשלום מקוונים. לאחר פנייה או בדיקת מחיר, נציג ג׳רבי טורס יחזור אליכם עם הצעה בכתב הכוללת את המחיר הסופי, פרטי הטיסה, כללי התעריף (כבודה, שינויים וביטולים) ודמי הטיפול.</li>
   <li>ההזמנה נעשית רק לאחר אישורכם המפורש להצעה ולאחר התשלום ב${fill('אמצעי תשלום וספק סליקה')}. העסקה נכרתת עם אישור ההזמנה בכתב מאיתנו.</li>
   <li>באחריותכם למסור שמות נוסעים זהים לשם בדרכון (באותיות לועזיות), תאריכי לידה ופרטי קשר נכונים. תיקון שם לאחר הנפקה עשוי להיות אסור או כרוך בעלות לפי כללי חברת התעופה.</li>
   <li>לאחר ההנפקה יישלחו אליכם הכרטיס/אישור ההזמנה וקבלה או חשבונית.</li></ul>`)}
  ${section('t-cancel', '5. ביטולים ושינויים', `<ul><li>ביטול או שינוי של כרטיס כפופים ל<strong>כללי התעריף של חברת התעופה</strong> שיפורטו בהצעה. כרטיסים רבים אינם ניתנים להחזר או לשינוי, או שהשינוי כרוך בדמי שינוי והפרשי מחיר.</li>
   <li>על ביטול או שינוי שאנו מטפלים בהם עבורכם ייגבו דמי טיפול של הסוכנות בסך ${fill('סכום דמי הטיפול לביטול/שינוי')}, בכפוף לדין ובכלל זה לתקרות שבחוק הגנת הצרכן.</li>
   <li>בקשות ביטול ושינוי יש לשלוח בכתב (מייל, וואטסאפ או טופס יצירת קשר). הבקשה תטופל בימי העבודה ${fill('ימים ושעות פעילות')}.</li>
   <li>ביטול או שינוי טיסה מצד חברת התעופה: הזכויות לפיצוי, להחזר ולסיוע מוקנות לפי הדין החל, לרבות חוק שירותי תעופה (פיצוי וסיוע בשל ביטול טיסה או שינוי בתנאיה), התשע״ב–2012, ובטיסות מאירופה לפי רגולציה EC 261/2004. נסייע לכם מול חברת התעופה; החובה לפצות היא של חברת התעופה.</li></ul>`)}
  ${section('t-consumer', '6. ביטול עסקה לפי חוק הגנת הצרכן', `<p>אם ההזמנה בוצעה בעסקת מכר מרחוק (בטלפון, במייל, בוואטסאפ או באינטרנט), עומדת לכם זכות ביטול לפי סעיף 14ג לחוק הגנת הצרכן, התשמ״א–1981, ותקנות הגנת הצרכן (ביטול עסקה), התשע״א–2010, בכפוף לתנאים ולחריגים שבהם — ובפרט לגבי שירותי נסיעה, הארחה ונופש שמועד מתן השירות קרוב למועד הביטול.</p>
   <p>במקרה של ביטול כדין ייגבו דמי ביטול שלא יעלו על הקבוע בדין, ובנוסף — ככל שהדין מתיר — סכומים ששולמו או שנדרש לשלם לספק או לחברת תעופה ואינם מוחזרים. ${fill('נוסח סופי של מנגנון דמי הביטול — לאחר בדיקת עורך דין')}.</p>
   <p>להודעת ביטול: מייל ${mailText()}, טלפון ${phoneText()} או טופס <a href="#/contact">יצירת קשר</a>. ציינו שם, מספר הזמנה ופרטי קשר.</p>`)}
  ${section('t-docs', '7. דרכונים, אשרות ובריאות', `<p>האחריות לדרכון בתוקף (ברוב המדינות — לפחות 6 חודשים ממועד החזרה), לאשרות כניסה ומעבר (כולל ESTA/ETA ודומיהם), לדרישות בריאות וחיסונים ולביטוח נסיעות חלה על הנוסעים. המידע שאנו מוסרים בנושא כללי ואינו תחליף לבדיקה מול נציגות המדינה או משרד החוץ. מומלץ מאוד לרכוש ביטוח נסיעות לחו״ל, כולל כיסוי לביטול.</p>`)}
  ${section('t-airline', '8. אחריות חברות התעופה והספקים', `<p>שירות ההובלה, לוחות הזמנים, הכבודה, הצ׳ק־אין, העלייה למטוס ושירותי הקרקע ניתנים ע״י חברות התעופה והספקים ובאחריותם, לפי תנאיהם. איחור, ביטול, שינוי מסלול, אובדן כבודה או נזק בטיסה הם באחריות חברת התעופה, בכפוף לאמנות הבינלאומיות ולדין. ג׳רבי טורס אחראית לשירות שהיא עצמה נותנת: דיוק במסירת המידע שקיבלה, ביצוע ההזמנה לפי אישורכם, וטיפול סביר בפניותיכם.</p>`)}
  ${section('t-liability', '9. הגבלת אחריות', `<p>ככל שהדין מתיר, אחריותנו לכל נזק הקשור להזמנה מוגבלת לסכום ששולם לנו בפועל עבור אותה הזמנה, ואיננו אחראים לנזק עקיף או תוצאתי. אין באמור כדי לגרוע מזכויות שאינן ניתנות להתניה לפי חוק הגנת הצרכן או כל דין אחר, או מאחריות לנזק שנגרם ברשלנות או בזדון.</p>`)}
  ${section('t-content', '10. תוכן, השראה ובוט שירות', `<p>מדריכים, המלצות, אומדנים ותשובות של ג׳רבי ובוט השירות ניתנים לנוחותכם ועשויים לכלול אי־דיוקים. תשובות אוטומטיות אינן מחייבות; התנאים המחייבים הם אלה שבהצעה ובאישור ההזמנה. בכל שאלה אפשר לבקש נציג אנושי.</p>`)}
  ${section('t-account', '11. חשבון לקוח', `<p>פתיחת חשבון היא רשות. שמרו על הסיסמה ועדכנו אותנו אם חשבתם שנעשה בחשבון שימוש לא מורשה. אפשר למחוק את החשבון בכל עת מהאזור האישי.</p>`)}
  ${section('t-privacy', '12. פרטיות', `<p>השימוש במידע אישי מתואר ב<a href="#/privacy">מדיניות הפרטיות</a>, שהיא חלק מתנאים אלה.</p>`)}
  ${section('t-ip', '13. קניין רוחני', `<p>התכנים, העיצוב, הסימנים, הדמות „ג׳רבי” והקוד באתר שייכים לג׳רבי טורס או לבעלי הזכויות בהם. אין להעתיק או לעשות בהם שימוש מסחרי בלי רשות בכתב.</p>`)}
  ${section('t-law', '14. דין ושיפוט', `<p>על תנאים אלה ועל כל עסקה באתר יחול הדין הישראלי בלבד. סמכות השיפוט הייחודית נתונה לבתי המשפט המוסמכים ב${fill('מחוז/עיר')}, בלי לגרוע מזכותו של צרכן לפנות לבית המשפט המוסמך לפי מקום מגוריו כפי שקובע הדין.</p>`)}
  ${section('t-contact', '15. יצירת קשר', `<p>ג׳רבי טורס · טלפון ${phoneText()} · מייל ${mailText()} · <a href="#/contact">טופס יצירת קשר</a> · כתובת: ${fill('כתובת למשלוח דואר')}.</p>`)}
  </div>`;
}

function privacy() {
  const items = [['p-who', 'מי אחראי למידע'], ['p-what', 'איזה מידע אנו אוספים'], ['p-why', 'למה אנו משתמשים במידע'], ['p-legal', 'האם חובה למסור מידע'], ['p-share', 'למי המידע מועבר'], ['p-abroad', 'העברה לחו״ל'], ['p-keep', 'כמה זמן שומרים'], ['p-device', 'עוגיות ואחסון במכשיר'], ['p-rights', 'הזכויות שלכם'], ['p-security', 'אבטחת מידע'], ['p-marketing', 'דיוור'], ['p-kids', 'קטינים'], ['p-changes', 'שינויים ויצירת קשר']];
  const row = (cat, examples, purpose, keep) => `<tr><th scope="row">${cat}</th><td>${examples}</td><td>${purpose}</td><td>${keep}</td></tr>`;
  return `${draft}<p class="micro-copy">עודכן לאחרונה: ${LEGAL_UPDATED}. המדיניות נכתבה לפי חוק הגנת הפרטיות, התשמ״א–1981, כפי שתוקן בתיקון 13 (בתוקף מאוגוסט 2025).</p>${toc(items)}<div class="article-body legal-body">
  ${section('p-who', '1. מי אחראי למידע', `<p>בעל השליטה במאגר: ג׳רבי טורס (${fill('שם הישות המשפטית וח.פ.')}). לפניות בנושא פרטיות: ${mailText()} · ${phoneText()}. ${fill('שם ממונה הגנת הפרטיות, אם ימונה')}.</p>`)}
  ${section('p-what', '2. איזה מידע אנו אוספים, למה ולכמה זמן', `<div class="table-scroll" tabindex="0" role="region" aria-label="טבלת סוגי המידע"><table class="legal-table"><caption class="sr-only">סוגי המידע, מטרתם ומשך השמירה</caption><thead><tr><th scope="col">סוג המידע</th><th scope="col">דוגמאות</th><th scope="col">מטרה</th><th scope="col">משך שמירה</th></tr></thead><tbody>
   ${row('חשבון לקוח (רשות)', 'שם, מייל, טלפון, סיסמה (כגיבוב חד־כיווני בלבד), הסכמה לדיוור ומועדה, טיולים וטיסות שמורים, מועדפים, עד 20 חיפושים אחרונים (בלי מחירים), תקציר פניות', 'מתן השירות בחשבון והמשך מכל מכשיר', 'עד מחיקת החשבון; התחברות — עד 30 יום')}
   ${row('פניות (לידים)', 'שם, טלפון, מייל, ערוץ מועדף, פרטי הטיול והבקשה, הסכמה ונוסחה', 'חזרה אליכם, הכנת הצעה ומתן שירות', fill('תקופת שמירת פניות'))}
   ${row('שיחות עם בוט השירות', 'תוכן ההודעות בשיחה, מזהה שיחה, ובוואטסאפ — מספר הטלפון', 'מענה, העברה לנציג ושיפור התשובות', 'עד 90 יום')}
   ${row('חיפושי טיסות ובדיקת מחיר', 'מסלול, תאריכים, הרכב נוסעים', 'הצגת טיסות ומחירים', 'במטמון זמני (דקות); לא נשמר עם שמכם אלא אם אתם מחוברים')}
   ${row('בקשות לג׳רבי (מתכנן)', 'טקסט הבקשה; בהסכמה ללמידה — מילות מפתח ותגיות עם מזהה מגובב', 'הבנת הבקשה ושיפור ההמלצות', 'עד 30 יום במטמון; נתוני למידה מצרפיים ללא זהות')}
   ${row('נתוני שימוש ואבטחה', 'כתובת IP, סוג דפדפן, זמני בקשות, יומני שגיאות', 'אבטחה, מניעת שימוש לרעה, הגבלת קצב', fill('תקופת שמירת יומנים'))}
   </tbody></table></div>
   <p>איננו אוספים באתר פרטי אשראי או מספרי דרכון. אל תשלחו אותם בבוט או בטפסים; פרטי נוסעים ותשלום נמסרים לנציג רק בשלב ההזמנה ובערוץ ${fill('ערוץ מאובטח להעברת פרטי נוסעים ותשלום')}.</p>`)}
  ${section('p-why', '3. למה אנו משתמשים במידע', `<ul><li>מתן השירות: חיפוש, בדיקת מחיר, הכנת הצעה, הזמנה ושירות לקוחות.</li><li>ניהול החשבון והשמירות שלכם.</li><li>מענה בבוט ובוואטסאפ והעברה לנציג.</li><li>שיפור ההמלצות והדירוג — באופן מצרפי ככל האפשר.</li><li>אבטחת האתר ומניעת הונאה ושימוש לרעה.</li><li>עמידה בחובות לפי דין (חשבונאות, מס, צרכנות).</li><li>דיוור שיווקי — רק אם הסכמתם במפורש.</li></ul>`)}
  ${section('p-legal', '4. האם חובה למסור מידע', `<p>אין חובה חוקית למסור לנו מידע. בלי פרטי קשר לא נוכל לחזור אליכם, ובלי פרטי הנוסעים לא נוכל להזמין עבורכם. אפשר לגלוש, לחפש ולשמור במכשיר בלי למסור פרטים.</p>`)}
  ${section('p-share', '5. למי המידע מועבר (מעבדי מידע וגורמים אחרים)', `<p>איננו מוכרים מידע אישי. המידע מועבר רק לגורמים שנדרשים לשירות, ורק בהיקף הנדרש:</p>
   <ul><li><strong>אחסון ותשתית:</strong> Vercel (אירוח האתר והשרת), Upstash (מסד נתונים בענן לחשבונות, פניות ושיחות).</li>
   <li><strong>ספקי טיסות וחברות תעופה:</strong> פרטי החיפוש; ובשלב ההזמנה — פרטי הנוסעים הנדרשים להנפקה.</li>
   <li><strong>מייל:</strong> Resend — לשליחת קודי אימות, איפוס סיסמה והודעות שירות.</li>
   <li><strong>וואטסאפ:</strong> Meta (WhatsApp Business Cloud API) — כשאתם פונים אלינו בוואטסאפ.</li>
   <li><strong>ספקי בינה מלאכותית:</strong> Anthropic${fill('ספקי AI נוספים, אם יתווספו')} — טקסט הבקשה או ההודעה בלבד, אחרי הסרת טלפונים ומיילים, כדי להבין את הבקשה ולנסח מענה. לא נשלחים שם או מזהה. לפי תנאי הספקים, המידע אינו משמש לאימון המודלים שלהם (${fill('לאמת מול חוזי הספקים')}).</li>
   <li><strong>גופנים:</strong> Google Fonts — הדפדפן טוען ממנו את הגופן ולכן נחשפת אליו כתובת ה־IP.</li>
   <li><strong>רשויות:</strong> כשהדין מחייב, או לשם הגנה על זכויותינו.</li></ul>`)}
  ${section('p-abroad', '6. העברת מידע אל מחוץ לישראל', `<p>חלק מהספקים שלמעלה מאחסנים או מעבדים מידע מחוץ לישראל (למשל באיחוד האירופי ובארה״ב), בכפוף לתקנות הגנת הפרטיות (העברת מידע אל מאגרי מידע שמחוץ לגבולות המדינה) ולהתחייבויות חוזיות של הספקים. ${fill('אזורי האחסון בפועל: Vercel / Upstash')}.</p>`)}
  ${section('p-keep', '7. כמה זמן שומרים', `<p>משך השמירה לכל סוג מידע מופיע בטבלה שלמעלה. בתום התקופה המידע נמחק או הופך לאנונימי, אלא אם הדין מחייב לשמור אותו זמן רב יותר (למשל מסמכים חשבונאיים).</p>`)}
  ${section('p-device', '8. עוגיות ואחסון במכשיר', `<p>האתר משתמש בעוגייה אחת בלבד, <span dir="ltr">gerbi_sid</span>, שנדרשת להתחברות לחשבון (מאובטחת, ל־30 יום). איננו משתמשים בעוגיות פרסום או במעקב של צד שלישי. בנוסף, האתר שומר במכשיר (localStorage / sessionStorage) מועדפים, טיולים וטיסות שמורים, השוואות, העדפות סגנון, הגדרות תצוגה ושיחת הבוט הנוכחית. ניקוי נתוני האתר בדפדפן מוחק אותם.</p>`)}
  ${section('p-rights', '9. הזכויות שלכם', `<ul><li><strong>עיון</strong> במידע שנשמר עליכם (סעיף 13 לחוק). בחשבון אפשר להוריד עותק מלא בכל עת.</li><li><strong>תיקון</strong> מידע שגוי, לא שלם או לא מעודכן (סעיף 14).</li><li><strong>מחיקה</strong> — מחיקת החשבון מהאזור האישי, או בקשה למחיקת פניות ושיחות.</li><li><strong>הסרה מדיוור</strong> בכל עת (סעיף 17ו לחוק ו־30א לחוק התקשורת).</li><li><strong>חזרה מהסכמה</strong> ללמידה ולדיוור — בהגדרות החשבון או בפנייה.</li></ul>
   <p>לבקשות: ${mailText()}. נשיב תוך ${fill('מספר ימים')} ולכל המאוחר בתוך המועדים שבדין. אם לא נעננו, אפשר לפנות לרשות להגנת הפרטיות.</p>`)}
  ${section('p-security', '10. אבטחת מידע', `<p>אנו נוקטים אמצעים סבירים לפי תקנות הגנת הפרטיות (אבטחת מידע), התשע״ז–2017: הצפנה בתעבורה (HTTPS), סיסמאות כגיבוב חד־כיווני, הגבלת ניסיונות התחברות, גישה מוגבלת לבעלי ההרשאה ויומני גישה. שום מערכת אינה חסינה לחלוטין; אם יתרחש אירוע אבטחה חמור, נפעל כנדרש בדין.</p>`)}
  ${section('p-marketing', '11. דיוור', `<p>נשלח דיוור שיווקי רק אם סימנתם הסכמה מפורשת. בכל הודעה יש דרך להסרה, ואפשר לבטל גם בחשבון.</p>`)}
  ${section('p-kids', '12. קטינים', `<p>השירות מיועד לבני 18 ומעלה. פרטי ילדים נמסרים לנו רק ע״י הורה או אפוטרופוס ורק לצורך ההזמנה.</p>`)}
  ${section('p-changes', '13. שינויים ויצירת קשר', `<p>נעדכן מדיניות זו מעת לעת; תאריך העדכון מופיע בראש הדף, ושינוי מהותי נפרסם גם באתר. שאלות: ${mailText()} · ${phoneText()} · <a href="#/contact">יצירת קשר</a>. ראו גם <a href="#/terms">תנאי השימוש</a>.</p>`)}
  </div>`;
}

function accessibility() {
  const done = ['קישור „דילוג לתוכן” בראש כל דף, וכותרת ראשית אחת לכל מסך שמקבלת פוקוס במעבר בין דפים.', 'ניווט מלא במקלדת: Tab ו־Shift+Tab, Enter ורווח להפעלה, Escape לסגירת חלונות; מסגרת פוקוס ברורה בכל רכיב.', 'בורר תאריכים נגיש: ניווט בחצים בין ימים (מימין לשמאל), Page Up/Down בין חודשים, ושדות תאריך להקלדה ישירה.', 'חלונות (תאריכים, נוסעים, בדיקת מחיר, צ׳אט השירות) מוכרזים כחלון, מחזירים את הפוקוס לכפתור שפתח אותם ותופסים את כל המסך בטלפון.', 'כל שדה בטפסים עם תווית; הודעות שגיאה מקושרות לשדה ומוכרזות, והפוקוס עובר לשדה הראשון השגוי.', 'הודעות מצב (תוצאות חיפוש, שמירה, תשובות הבוט) מוכרזות לקוראי מסך (aria-live).', 'אזורי דף (כותרת, ניווט, תוכן, כותרת תחתונה) מסומנים, ושפת הדף וכיוונו (עברית, מימין לשמאל) מוגדרים.', 'ניגודיות צבעים לפי רמה AA, טקסט ניתן להגדלה עד 200% בלי אובדן תוכן, ופריסה שמתאימה את עצמה לרוחב 320 פיקסלים.', 'כפתורים ויעדי מגע בגודל 44×44 פיקסלים לפחות בטלפון, ושדות הקלט בגודל שאינו גורם להגדלה אוטומטית.', 'כיבוד הגדרת „הפחתת תנועה” של המכשיר, ואפשרות לעצור אנימציות בהגדרות התצוגה.', 'לתמונות תוכן יש טקסט חלופי; אייקונים קישוטיים מוסתרים מקוראי מסך.'];
  const limits = ['פרטי טיסות (קודי חברות, שעות ושמות שדות תעופה) מגיעים מהספקים ומוצגים כפי שהתקבלו; ייתכנו קיצורים לועזיים.', 'תמונות בפוסטים בבלוג שמעלה צוות האתר עשויות להיות חסרות תיאור חלופי מלא — אנו פועלים להשלים זאת.', 'תשובות בוט השירות נוצרות אוטומטית; בכל שלב אפשר לבקש נציג אנושי.', 'שירותים חיצוניים (וואטסאפ, אתרי חברות התעופה) אינם בשליטתנו ונגישותם באחריות מפעיליהם.', `טרם בוצעה בדיקה ע״י מורשה/ית נגישות שירות ובדיקה עם משתמשי קוראי מסך. ${fill('תאריך בדיקת מורשה נגישות, אם בוצעה')}`];
  return `<div class="article-body legal-body">
  ${section('a-commit', 'המחויבות שלנו', `<p>ג׳רבי טורס רואה חשיבות במתן שירות שוויוני לכל הלקוחות, ובהם אנשים עם מוגבלות. השקענו בהנגשת האתר כך שיהיה נוח לשימוש עם מקלדת, קורא מסך, הגדלת תצוגה ומכשירים ניידים.</p>`)}
  ${section('a-level', 'רמת ההנגשה', `<p>האתר הותאם לדרישות תקנות שוויון זכויות לאנשים עם מוגבלות (התאמות נגישות לשירות), התשע״ג–2013, ולתקן הישראלי ת״י 5568 ברמה AA, המבוסס על הנחיות WCAG 2.0 (ובדקנו גם מול WCAG 2.1 ברמה AA). הבדיקה בוצעה בדפדפני Chrome ו־Safari במחשב ובטלפון (iOS ו־Android), במקלדת בלבד ובכלי בדיקה אוטומטיים (axe-core).</p>`)}
  ${section('a-done', 'מה הונגש באתר', `<ul>${done.map(t => `<li>${t}</li>`).join('')}</ul>`)}
  ${section('a-limits', 'מגבלות ידועות', `<p>למרות מאמצינו, ייתכן שחלקים באתר עדיין אינם נגישים במלואם:</p><ul>${limits.map(t => `<li>${t}</li>`).join('')}</ul><p>אם נתקלתם בקושי, נשמח שתספרו לנו ונטפל בכך ובינתיים נעניק לכם את השירות בדרך חלופית (טלפון, מייל או וואטסאפ).</p>`)}
  ${section('a-physical', 'הסדרי נגישות בשירות', `<p>${fill('האם יש משרד שמקבל קהל. אם כן — כתובת, חניית נכים, נגישות הכניסה, שירותים נגישים ושעות; אם לא — „השירות ניתן בטלפון, במייל, בוואטסאפ ובאתר בלבד”')}.</p><p>בקשות נגישות לחופשה עצמה (כיסא גלגלים בשדה התעופה, חדר נגיש, ליווי) — אפשר לציין בטופס הפנייה או בתכנון הטיול, ונבדוק אותן מול הספקים.</p>`)}
  ${section('a-contact', 'רכז/ת הנגישות ופניות', `<dl class="legal-dl"><dt>שם</dt><dd>${fill('שם רכז/ת הנגישות')}</dd><dt>טלפון</dt><dd>${fill('טלפון ישיר')}</dd><dt>מייל</dt><dd>${fill('מייל לפניות נגישות')}</dd><dt>כתובת למשלוח דואר</dt><dd>${fill('כתובת')}</dd></dl><p>אפשר לפנות גם בטלפון ${phoneText()}, במייל ${mailText()} או ב<a href="#/contact">טופס יצירת קשר</a>. נשיב בתוך ${fill('מספר ימי עבודה')}.</p>`)}
  ${section('a-date', 'עדכון ההצהרה', `<p>בדיקת הנגישות האחרונה: <time datetime="2026-11-15">${LAST_A11Y_CHECK}</time>. ההצהרה עודכנה בתאריך <time datetime="2026-11-15">${LAST_A11Y_CHECK}</time>.</p>`)}
  </div>`;
}

// English (spec 21): draft translations in locales/legal-en.mjs, built with the same helpers; the Hebrew text prevails.
const enDate = () => fmtDate('2026-11-15', { day: 'numeric', month: 'long', year: 'numeric' });
const enHelpers = () => ({ fill, phone: phoneText, mail: mailText, section, toc, draft, updated: enDate(), a11yCheck: enDate() });

export function legalRoutes() {
  const en = lang === 'en';
  const page = (crumb, kicker, title, lead, body) => ({ view, footer, bread, heading }) => {
    view.innerHTML = `<div class="article-width legal-page">${bread(crumb)}${heading(kicker, title, lead)}${body()}</div>${footer}`;
  };
  return {
    terms: page(t('content.legal.terms.crumb'), t('content.legal.goodToKnow'), t('content.legal.terms.title'), t('content.legal.terms.lead'), en ? () => termsEn(enHelpers()) : terms),
    privacy: page(t('content.legal.privacy.crumb'), t('content.legal.goodToKnow'), t('content.legal.privacy.title'), t('content.legal.privacy.lead'), en ? () => privacyEn(enHelpers()) : privacy),
    accessibility: page(t('content.legal.a11y.crumb'), t('content.legal.goodToKnow'), t('content.legal.a11y.title'), t('content.legal.a11y.lead'), () => displaySettingsHtml() + (en ? accessibilityEn(enHelpers()) : accessibility())),
  };
}
